import { useState } from "react";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { api } from "../../api/base44Client";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "../ui/dialog";
import { Button } from "../ui/button";
import { Input } from "../ui/input";
import { Label } from "../ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "../ui/tabs";
import { PlusCircle, MinusCircle, Loader2 } from "lucide-react";
import { cn } from "../../lib/utils";
import { formatCurrency } from "../../lib/format";

export default function CashManagementModal({ open, onClose, portfolio, transactions }) {
  const [type, setType] = useState("deposit");
  const [amount, setAmount] = useState("");
  const [note, setNote] = useState("");
  const queryClient = useQueryClient();

  const createTransaction = useMutation({
    mutationFn: async (data) => {
      return api.cash.createTransaction(data);
    },
    onSuccess: (response) => {
      // Bug fix (this session): this previously invalidated "portfolios" (plural),
      // which matches no query key actually used anywhere in the app (Dashboard.js
      // and Layout.js's global trigger both key their portfolio query "portfolioApi";
      // Positions.js uses "portfolio"). The cash balance shown elsewhere never
      // refreshed after a deposit/withdrawal as a result. Invalidate every key in
      // use so this stays correct regardless of which page/component is mounted.
      queryClient.invalidateQueries({ queryKey: ["portfolioApi"] });
      queryClient.invalidateQueries({ queryKey: ["portfolio"] });
      queryClient.invalidateQueries({ queryKey: ["portfolios"] });
      queryClient.invalidateQueries({ queryKey: ["cashTransactions"] });
      setAmount("");
      setNote("");
      toast.success(
        type === "deposit"
          ? `${formatCurrency(Number(response?.amount ?? amount))} deposited.`
          : `${formatCurrency(Number(response?.amount ?? amount))} withdrawn.`
      );
      onClose();
    },
    onError: (error) => {
      toast.error(error?.data?.detail || error?.message || "Failed to create transaction");
    }
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!amount || parseFloat(amount) <= 0) return;
    
    createTransaction.mutate({
      type,
      amount: parseFloat(amount),
      note,
      date: new Date().toISOString().split("T")[0]
    });
  };

  // Defensive: guard against a non-array `transactions` prop (e.g. an unstubbed
  // test route or an unexpected API shape) rather than crashing the component —
  // `Array.isArray` check added after this exact TypeError ("transactions.slice
  // is not a function") crashed the whole app via Layout.js's now-global query.
  const recentTransactions = Array.isArray(transactions) ? transactions.slice(0, 5) : [];

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="bg-slate-900 border-slate-800 text-white max-w-md">
        <DialogHeader>
          <DialogTitle>Cash Management</DialogTitle>
        </DialogHeader>

        <div className="mb-4 p-4 rounded-xl bg-slate-800/50 border border-slate-700">
          <p className="text-sm text-slate-600 dark:text-slate-400">Current Cash Balance</p>
          <p className="text-2xl font-bold text-white">
            {formatCurrency(portfolio?.cash_balance || 0)}
          </p>
        </div>

        <Tabs value={type} onValueChange={setType}>
          <TabsList className="grid grid-cols-2 bg-slate-800">
            <TabsTrigger value="deposit" className="data-[state=active]:bg-emerald-500/20 data-[state=active]:text-emerald-400">
              <PlusCircle className="w-4 h-4 mr-2" />
              Deposit
            </TabsTrigger>
            <TabsTrigger value="withdrawal" className="data-[state=active]:bg-rose-500/20 data-[state=active]:text-rose-400">
              <MinusCircle className="w-4 h-4 mr-2" />
              Withdraw
            </TabsTrigger>
          </TabsList>

          <form onSubmit={handleSubmit} className="mt-4 space-y-4">
            <div>
              <Label htmlFor="amount">Amount (£)</Label>
              <Input
                id="amount"
                type="number"
                step="0.01"
                min="0"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0.00"
                className="bg-slate-800 border-slate-700 mt-1"
              />
            </div>
            <div>
              <Label htmlFor="note">Note (optional)</Label>
              <Input
                id="note"
                value={note}
                onChange={(e) => setNote(e.target.value)}
                placeholder="e.g., Monthly deposit"
                className="bg-slate-800 border-slate-700 mt-1"
              />
            </div>
            <Button 
              type="submit" 
              disabled={createTransaction.isPending || !amount}
              className={cn(
                "w-full",
                type === "deposit" 
                  ? "bg-emerald-600 hover:bg-emerald-700" 
                  : "bg-rose-600 hover:bg-rose-700"
              )}
            >
              {createTransaction.isPending && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {type === "deposit" ? "Add Funds" : "Withdraw Funds"}
            </Button>
          </form>
        </Tabs>

        {recentTransactions.length > 0 && (
          <div className="mt-6 pt-4 border-t border-slate-800">
            <p className="text-sm font-medium text-slate-600 dark:text-slate-400 mb-3">Recent Transactions</p>
            <div className="space-y-2">
              {recentTransactions.map((tx) => (
                <div key={tx.id} className="flex items-center justify-between text-sm">
                  <div className="flex items-center gap-2">
                    {tx.type === "withdrawal" ? (
                      <MinusCircle className="w-4 h-4 text-rose-400" />
                    ) : (
                      <PlusCircle className="w-4 h-4 text-emerald-400" />
                    )}
                    <span className="text-slate-300">{tx.note || tx.type}</span>
                  </div>
                  <span className={tx.type === "withdrawal" ? "text-rose-400" : "text-emerald-400"}>
                    {formatCurrency(tx.type === "withdrawal" ? -Math.abs(tx.amount) : Math.abs(tx.amount), { signed: true })}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}
